const BANK_TKP_BARU = [
{a:"pelayanan", q:"Seorang pasien lansia di puskesmas kebingungan menggunakan mesin antrean digital dan hampir pulang karena menyerah. Sikap Anda...", o:[["Menghampiri, membantu mengambil nomor antrean, lalu mengusulkan petugas pendamping di dekat mesin untuk pasien lansia lainnya",5],["Menghampiri dan membantu pasien tersebut mengambil nomor antrean sampai ia duduk menunggu dengan tenang di ruang tunggu",4],["Menyarankan pasien bertanya kepada petugas pendaftaran yang sedang bertugas",3],["Membiarkan karena Anda sedang mengerjakan berkas lain",2],["Mengatakan bahwa mesin itu mudah dan pasien harus belajar sendiri",1]], p:"Membantu langsung sekaligus mengusulkan perbaikan layanan bagi kelompok rentan adalah sikap paling proaktif dan tuntas. Membiarkan atau menyalahkan pasien jelas tidak mencerminkan pelayanan yang empatik."},
{a:"pelayanan", q:"Seorang warga pengguna kursi roda datang ke kantor kelurahan, tetapi loket pelayanan berada di lantai dua yang hanya memiliki tangga. Yang Anda lakukan...", o:[["Memindahkan layanan ke lantai satu untuk sementara, menyelesaikan urusannya, lalu melaporkan kebutuhan jalur ramah difabel kepada pimpinan",5],["Membawa berkas dan formulir turun ke lantai satu agar warga tersebut dapat dilayani di sana dengan nyaman sampai selesai urusannya",4],["Meminta warga menunggu sementara Anda menanyakan solusi kepada atasan",3],["Menyarankan warga mewakilkan urusan kepada keluarga yang bisa naik tangga",2],["Mengatakan bahwa itu sudah aturan gedung dan tidak bisa diubah",1]], p:"Layanan harus mendatangi warga yang kesulitan, bukan sebaliknya, ditambah usulan perbaikan agar masalah tidak berulang. Opsi 1 dan 2 menunjukkan sikap tidak peduli pada hak warga difabel."},
{a:"pelayanan", q:"Seorang pemohon paspor membawa berkas yang kurang satu dokumen dan sudah datang dari kota yang jauh. Sikap Anda...", o:[["Menjelaskan kekurangannya, memberi tahu cara mengurusnya secepat mungkin, dan mencatat nomor kontak agar bisa dibantu saat kembali",5],["Menjelaskan dokumen yang kurang dengan ramah beserta cara melengkapinya agar pemohon tidak salah langkah lagi nanti",4],["Menolak berkas dan meminta pemohon membaca persyaratan di papan pengumuman",3],["Menerima berkas apa adanya agar pemohon tidak marah",2],["Menyalahkan pemohon yang tidak membaca persyaratan lebih teliti",1]], p:"Pelayanan terbaik menjelaskan, mengarahkan, dan memudahkan kunjungan berikutnya tanpa melanggar persyaratan. Menerima berkas tidak lengkap melanggar SOP, sedangkan menyalahkan pemohon merusak citra layanan."},
{a:"pelayanan", q:"Seorang wajib pajak menanyakan hal yang bukan bidang loket Anda, padahal antrean di belakangnya masih panjang. Yang Anda lakukan...", o:[["Mengantarkan ke loket yang tepat, menyampaikan singkat keperluannya kepada petugas di sana, lalu kembali melayani antrean",5],["Menjelaskan secara rinci loket mana yang menangani pertanyaannya beserta dokumen yang perlu dibawa agar tidak bolak-balik",4],["Menyuruh wajib pajak bertanya ke petugas informasi",3],["Menjawab seadanya saja agar antrean cepat berjalan",2],["Mengatakan bahwa itu bukan urusan Anda dan meminta pindah",1]], p:"Mengantar dan menyampaikan keperluan menjamin urusan warga tuntas tanpa mengorbankan antrean lain. Menjawab asal atau menolak mentah-mentah merugikan warga."},
{a:"pelayanan", q:"Pengunjung perpustakaan daerah mengeluh buku yang tertera tersedia di katalog daring ternyata tidak ada di rak. Sikap Anda...", o:[["Membantu mencari ke bagian sirkulasi, menawarkan buku serupa, lalu melaporkan ketidaksesuaian data agar katalog segera diperbarui",5],["Mencari buku itu bersama pengunjung dan menawarkan alternatif buku lain yang membahas topik yang sama dengan lengkap",4],["Menyampaikan bahwa data katalog memang kadang belum diperbarui",3],["Meminta pengunjung kembali lain waktu",2],["Mengatakan pengunjung salah membaca katalog",1]], p:"Membantu pengunjung sekaligus melaporkan kesalahan data memperbaiki layanan di masa depan. Opsi bawah hanya menunda atau menyalahkan pengguna."},
{a:"pelayanan", q:"Seorang warga lanjut usia yang tidak bisa membaca datang ke kantor desa untuk mengurus surat keterangan. Yang Anda lakukan...", o:[["Membacakan dan membantu mengisi formulir, memastikan ia paham isinya, lalu menandatangani setelah dikonfirmasi",5],["Mengisikan formulir untuknya sambil membacakan tiap bagian agar ia mengetahui isi surat yang akan diterima nanti",4],["Memintanya membawa anggota keluarga yang bisa membaca",3],["Meminta ia mengisi sendiri sebisanya",2],["Menolak melayani karena formulir belum diisi",1]], p:"Warga dengan keterbatasan literasi perlu pendampingan sampai tuntas dan paham. Meminta orang lain atau menolak berarti menghambat hak layanan."},
{a:"pelayanan", q:"Selesai mengurus KTP elektronik, seorang warga menyodorkan uang sebagai tanda terima kasih dan menyebutnya tidak apa-apa. Sikap Anda...", o:[["Menolak dengan sopan, menjelaskan bahwa layanan gratis, dan mengarahkannya mengisi survei kepuasan sebagai bentuk apresiasi",5],["Menolak halus sambil menjelaskan bahwa pegawai dilarang menerima pemberian apa pun dalam bentuk uang maupun barang",4],["Menerima lalu menyerahkannya ke kotak amal kantor",3],["Menerima karena ia memberi dengan ikhlas",2],["Meminta tambahan agar prosesnya lebih cepat lain kali",1]], p:"Menolak dengan santun dan memberi jalur apresiasi yang benar menjaga integritas layanan. Menerima pemberian dalam bentuk apa pun termasuk gratifikasi."},
{a:"pelayanan", q:"Saat jam istirahat, seorang warga mendatangi loket dan membutuhkan surat keterangan kematian untuk keperluan pemakaman hari itu. Yang Anda lakukan...", o:[["Segera melayani karena kondisi darurat, lalu memberi tahu rekan dan atasan bahwa Anda menunda istirahat",5],["Memanggil rekan yang bertugas agar surat diproses cepat, sambil menenangkan keluarga yang sedang berduka tersebut",4],["Meminta warga menunggu sampai jam istirahat selesai",3],["Menyarankan warga datang besok pagi",2],["Menyuruh warga pergi karena loket tutup",1]], p:"Kondisi darurat kemanusiaan menuntut layanan segera tanpa mengabaikan koordinasi. Menyuruh menunggu atau pulang mengabaikan empati."},
{a:"pelayanan", q:"Hasil survei kepuasan masyarakat di kantor Anda menunjukkan keluhan utama berupa antrean panjang pada pagi hari. Sikap Anda...", o:[["Menganalisis jam puncak, mengusulkan sistem antrean daring atau penambahan loket sementara, lalu ikut menguji coba usulan itu",5],["Mengusulkan penambahan petugas pada jam sibuk dalam rapat evaluasi dengan data jumlah pengunjung per jam",4],["Menunggu keputusan pimpinan atas hasil survei",3],["Menganggap keluhan antrean hal yang wajar",2],["Mempertanyakan kejujuran responden survei",1]], p:"Hasil survei harus ditindaklanjuti dengan usulan konkret dan keterlibatan nyata. Menunggu atau mengabaikan tidak menyelesaikan masalah."},
{a:"pelayanan", q:"Seorang pasien tanpa kartu jaminan kesehatan datang ke rumah sakit dalam keadaan lemah dan keluarganya kebingungan soal administrasi. Yang Anda lakukan...", o:[["Memastikan pasien ditangani lebih dulu, lalu membantu keluarga mengurus kepesertaan sesuai prosedur sambil menjelaskan alurnya",5],["Membantu keluarga mengisi data sementara agar pasien segera diperiksa, lalu menjelaskan dokumen apa saja yang perlu dilengkapi kemudian",4],["Meminta keluarga menyelesaikan administrasi dulu baru pasien diperiksa",3],["Mengarahkan keluarga ke rumah sakit lain",2],["Menolak pasien karena tidak membawa kartu",1]], p:"Keselamatan pasien didahulukan, administrasi diselesaikan beriringan dengan pendampingan. Menolak atau menunda penanganan membahayakan warga."},
{a:"pelayanan", q:"Seorang warga bertanya status izin usahanya yang sudah dua minggu hanya berstatus diproses di sistem. Sikap Anda...", o:[["Mengecek tahap berkasnya, menghubungi bagian terkait, lalu memberi kepastian perkiraan selesai dan mengabarkan perkembangannya",5],["Mengecek status di sistem dan menjelaskan tahapan yang sedang dilalui beserta batas waktu layanan yang berlaku",4],["Menyarankan warga bertanya langsung ke bagian verifikasi",3],["Meminta warga bersabar saja",2],["Mengatakan sistem bukan urusan Anda",1]], p:"Warga butuh kepastian, sehingga menelusuri dan menindaklanjuti ke bagian terkait adalah pelayanan paling tuntas. Melempar atau meminta sabar saja tidak memberi solusi."},
{a:"pelayanan", q:"Keluarga seorang warga binaan di lapas bingung dengan aturan jadwal kunjungan dan hampir membawa barang yang dilarang. Yang Anda lakukan...", o:[["Menjelaskan aturan dan alasannya dengan ramah, menunjukkan barang yang boleh dibawa, lalu membagikan lembar panduan agar mereka paham",5],["Menjelaskan jadwal dan barang terlarang secara rinci beserta alasan keamanannya kepada keluarga tersebut di ruang tunggu",4],["Menyuruh mereka membaca papan aturan",3],["Menyita barang tanpa penjelasan",2],["Memarahi mereka karena tidak tahu aturan",1]], p:"Menjelaskan aturan dengan ramah dan memberi panduan tertulis mencegah pelanggaran berulang. Menyita tanpa penjelasan atau memarahi tidak sesuai pelayanan prima."},
{a:"pelayanan", q:"Seorang korban banjir datang ke kantor penanggulangan bencana meminta bantuan, tetapi data dirinya belum lengkap dan ia terlihat sangat cemas. Sikap Anda...", o:[["Memberikan bantuan darurat lebih dulu, membantu melengkapi data di tempat, lalu menenangkan dan menjelaskan tahap bantuan berikutnya",5],["Membantu melengkapi data bersama korban secepatnya sambil menenangkan dan menjelaskan langkah yang akan ditempuh selanjutnya",4],["Meminta korban kembali setelah datanya lengkap",3],["Mengarahkan korban ke kelurahan untuk mendata",2],["Mengatakan bantuan hanya untuk yang datanya lengkap",1]], p:"Dalam situasi darurat, kebutuhan dasar didahulukan sambil melengkapi administrasi. Menunda atau menolak karena data kurang mengabaikan tujuan layanan."},
{a:"pelayanan", q:"Seorang warga berpenampilan lusuh sudah antre lama, lalu seorang pengusaha berpakaian rapi meminta dilayani lebih dulu. Yang Anda lakukan...", o:[["Menjelaskan sopan bahwa layanan sesuai urutan, melayani warga tersebut, dan menawarkan pengusaha mengambil nomor atau jalur daring",5],["Tetap melayani sesuai urutan antrean dan meminta pengusaha menunggu giliran dengan sopan tanpa membedakan siapa pun",4],["Melayani pengusaha sebentar karena urusannya singkat",3],["Melayani pengusaha agar tidak tersinggung",2],["Menyuruh warga lusuh mengalah",1]], p:"Pelayanan harus adil tanpa membedakan penampilan atau status. Mendahulukan seseorang karena status merupakan diskriminasi."},
{a:"pelayanan", q:"Lewat kotak saran, seorang pengunjung menulis bahwa toilet umum di kantor Anda kotor dan tidak berfungsi baik. Sikap Anda...", o:[["Mengecek kondisi toilet, melaporkan ke bagian umum, lalu mengusulkan jadwal pemeriksaan kebersihan dan menindaklanjuti sampai diperbaiki",5],["Meneruskan keluhan itu ke bagian umum dengan foto kondisi terkini agar segera ditangani dan dibersihkan",4],["Menunggu petugas kebersihan menemukannya sendiri",3],["Menganggap keluhan itu berlebihan",2],["Membuang kertas saran itu karena memalukan kantor",1]], p:"Kotak saran adalah sarana perbaikan, sehingga keluhan perlu ditindaklanjuti sampai tuntas. Mengabaikan atau menutupi keluhan melanggar semangat pelayanan publik."},
{a:"pelayanan", q:"Seorang warga dari desa tetangga meminta surat domisili di kantor desa Anda dan mengaku sudah dua kali ditolak di tempat lain. Yang Anda lakukan...", o:[["Memeriksa persyaratannya, menjelaskan kewenangan desa, lalu menghubungi desa asalnya agar urusannya terselesaikan tanpa bolak-balik",5],["Memeriksa persyaratan dan menjelaskan kewenangan desa dengan ramah beserta langkah yang harus ditempuh warga tersebut",4],["Menyarankan warga mengurus ke desanya sendiri",3],["Menunda sampai ada petunjuk dari atasan yang lebih tinggi",2],["Menolak karena bukan warga desa ini",1]], p:"Menghubungi pihak terkait membuat urusan warga tuntas tanpa melanggar kewenangan. Menolak atau menyuruh pulang membuat warga kembali bolak-balik."},
{a:"jejaring", q:"Dua unit di kantor Anda saling melempar tanggung jawab atas laporan bersama yang tenggatnya tinggal tiga hari. Sikap Anda...", o:[["Mengajak kedua unit berkoordinasi, membagi tugas jelas, dan memantau kemajuannya",5],["Mengusulkan rapat singkat bersama kedua unit untuk membagi peran, menyepakati tenggat tiap bagian, dan menunjuk satu penghubung",4],["Menyerahkan penyelesaian kepada atasan kedua unit",3],["Menunggu salah satu unit mengalah lebih dulu",2],["Menyalahkan unit yang dianggap malas di depan banyak orang",1]], p:"Inisiatif mempertemukan dua pihak dan membagi peran menyelesaikan akar masalah. Menyalahkan atau menunggu hanya memperburuk kerja sama."},
{a:"jejaring", q:"Dalam rapat koordinasi lintas dinas, perwakilan salah satu dinas tidak hadir, padahal keputusan rapat menyangkut tugas mereka. Yang Anda lakukan...", o:[["Mengirim risalah rapat dan menghubungi dinas itu untuk menjelaskan keputusan serta meminta tanggapan",5],["Mencatat hasil rapat dengan rapi, mengirimkannya kepada dinas yang absen, lalu menjadwalkan pertemuan lanjutan bersama mereka secepatnya",4],["Menunggu mereka bertanya sendiri kepada panitia",3],["Meneruskan rapat dan menganggap mereka setuju",2],["Mengeluhkan ketidakhadiran mereka kepada peserta lain",1]], p:"Menjaga informasi tetap sampai dan meminta tanggapan memastikan koordinasi tetap utuh. Mengasumsikan persetujuan atau bergunjing merusak hubungan antarinstansi."},
{a:"jejaring", q:"Anda mengetahui informasi tentang program bantuan yang berguna bagi unit lain, tetapi unit itu belum mengetahuinya. Sikap Anda...", o:[["Segera menyampaikan informasi tersebut kepada unit terkait beserta dokumen pendukungnya",5],["Membagikan informasi itu di grup koordinasi lengkap dengan tautan sumber, kontak penanggung jawab, dan batas waktu pendaftarannya",4],["Menyampaikan jika ada yang menanyakan",3],["Menyimpan informasi untuk keperluan unit sendiri",2],["Mengabaikan karena bukan tugas unit Anda",1]], p:"Berbagi informasi secara proaktif memperkuat kerja sama lintas unit. Menyimpan atau menunggu ditanya merugikan organisasi."},
{a:"jejaring", q:"Seorang rekan dari unit lain berselisih dengan Anda tentang pemakaian ruang rapat yang jadwalnya bertabrakan. Yang Anda lakukan...", o:[["Mengajak berbicara tenang, mencari jadwal pengganti yang cocok, lalu menyepakati sistem pemesanan ruang bersama",5],["Menawarkan menggeser jadwal rapat Anda jika rapat mereka lebih mendesak, lalu membahas cara agar jadwal tidak bentrok lagi",4],["Melaporkan ke bagian umum agar mereka yang memutuskan",3],["Tetap memakai ruangan karena Anda memesan lebih dulu",2],["Mengabaikan rekan itu dan tidak menyapanya lagi",1]], p:"Mencari solusi bersama sekaligus membenahi sistem menjaga hubungan kerja. Memaksakan kehendak atau mendiamkan merusak relasi."},
{a:"jejaring", q:"Anda ditugaskan mengoordinasikan vaksinasi di sekolah bersama pihak puskesmas yang jadwalnya padat. Yang Anda lakukan...", o:[["Menemui pihak puskesmas, menyesuaikan jadwal dengan sekolah, lalu menetapkan penghubung tetap agar komunikasi lancar",5],["Menghubungi puskesmas dan sekolah untuk mencocokkan tanggal pelaksanaan serta jumlah peserta yang akan divaksin dalam satu pertemuan",4],["Mengirim surat resmi lalu menunggu balasan",3],["Meminta atasan menghubungi puskesmas",2],["Membatalkan kegiatan karena jadwal sulit dicocokkan",1]], p:"Koordinasi aktif dengan penghubung tetap membuat kegiatan lintas instansi berjalan. Menunggu, melempar, atau membatalkan menghambat program."},
{a:"jejaring", q:"Anda memerlukan data dari instansi lain dan memiliki kenalan lama di sana yang bisa memberikannya tanpa surat resmi. Sikap Anda...", o:[["Menghubungi kenalan itu untuk dipandu prosedur resmi, lalu mengajukan permintaan data secara tertulis",5],["Meminta tolong kenalan agar membantu mempercepat proses permintaan resmi yang sudah Anda ajukan melalui surat",4],["Meminta datanya tanpa surat dengan janji mengirim suratnya nanti",3],["Meminta datanya diam-diam agar tidak diketahui atasan",2],["Mengancam menyebarkan masalah jika data tidak diberikan",1]], p:"Relasi pribadi sebaiknya dipakai untuk memperlancar jalur resmi, bukan menggantikannya. Jalan pintas atau tekanan melanggar aturan dan etika."},
{a:"jejaring", q:"Seorang rekan baru di tim Anda tampak canggung dan jarang berbicara dengan siapa pun. Yang Anda lakukan...", o:[["Mengajaknya makan siang bersama, memperkenalkannya ke rekan lain, lalu melibatkannya dalam tugas tim",5],["Menyapa dan menawarkan bantuan jika ia memerlukan penjelasan tentang pekerjaan atau kebiasaan di kantor ini",4],["Menunggu sampai ia terbiasa sendiri",3],["Membiarkannya karena ia pasti punya alasan",2],["Mengejeknya sebagai orang yang sombong",1]], p:"Menyambut anggota baru membangun kebersamaan dan kinerja tim. Membiarkan atau mengejek menciptakan jarak."},
{a:"jejaring", q:"Kegiatan bakti sosial bersama komunitas warga kekurangan relawan dua hari menjelang pelaksanaan. Sikap Anda...", o:[["Mengajak rekan kantor dan menghubungi tokoh warga untuk menambah relawan, lalu menyusun pembagian tugas",5],["Menyebarkan ajakan lewat grup kantor dan komunitas lengkap dengan jadwal serta tugas yang masih membutuhkan tenaga tambahan",4],["Menyampaikan kekurangan itu kepada panitia saja",3],["Menyarankan kegiatan ditunda",2],["Mengundurkan diri karena panitia kurang siap",1]], p:"Memanfaatkan jaringan untuk menutup kekurangan menunjukkan kolaborasi nyata. Menunda atau mundur meninggalkan tanggung jawab bersama."},
{a:"jejaring", q:"Dua rekan satu tim Anda bertengkar karena pembagian tugas, sehingga suasana kerja menegang dan pekerjaan terhambat. Yang Anda lakukan...", o:[["Menemui keduanya satu per satu, mempertemukan mereka dengan netral, dan membantu menyepakati pembagian tugas",5],["Mengajak kedua rekan berbicara dalam suasana santai agar mereka bisa saling memahami sudut pandang masing-masing dan berdamai",4],["Melaporkan pertengkaran itu kepada atasan",3],["Berpihak pada rekan yang lebih dekat dengan Anda",2],["Menceritakan pertengkaran itu kepada rekan lain",1]], p:"Menjadi penengah netral memulihkan hubungan kerja. Berpihak atau menyebarkan masalah memperkeruh suasana."},
{a:"jejaring", q:"Anda menerima undangan forum diskusi antarinstansi yang topiknya relevan, sementara atasan Anda berhalangan hadir. Sikap Anda...", o:[["Meminta izin menggantikan, hadir, lalu melaporkan hasil forum dan menjalin kontak dengan peserta",5],["Meminta izin menghadiri forum tersebut mewakili atasan dan menyusun catatan penting untuk dibagikan kepada seluruh anggota tim",4],["Membiarkan undangan sampai atasan memutuskan",3],["Mengabaikan karena bukan tugas Anda",2],["Menolak undangan tanpa memberi kabar",1]], p:"Forum antarinstansi adalah kesempatan membangun jejaring dan berbagi pengetahuan. Mengabaikan undangan menutup peluang kerja sama."},
{a:"jejaring", q:"Seorang rekan di cabang lain bertanya cara kerja aplikasi yang Anda kuasai, padahal Anda sedang sibuk. Yang Anda lakukan...", o:[["Menjadwalkan waktu singkat untuk menjelaskan, lalu mengirimkan panduan ringkas agar ia bisa mengulang",5],["Membalas bahwa Anda sibuk, lalu menawarkan jadwal bantuan dan mengirim tautan panduan dengan penjelasan langkah awal",4],["Menyuruhnya membaca buku petunjuk",3],["Mengatakan tidak punya waktu",2],["Menolak karena itu bukan urusan cabang Anda",1]], p:"Berbagi pengetahuan dengan menyesuaikan waktu menjaga hubungan antarcabang. Menolak mentah-mentah menutup kerja sama."},
{a:"jejaring", q:"Dalam proyek penataan lingkungan bersama pihak desa, kepala desa belum membalas pesan Anda selama beberapa hari. Sikap Anda...", o:[["Mendatangi kantor desa langsung, memaparkan rencana, lalu menyepakati jalur komunikasi yang mudah",5],["Menghubungi perangkat desa lain agar pesan sampai, sambil mengirim ringkasan rencana beserta tenggat yang harus disepakati bersama",4],["Menunggu balasan sampai ada kabar",3],["Menganggap desa tidak berminat bekerja sama",2],["Melanjutkan proyek tanpa melibatkan desa",1]], p:"Jemput bola dan menyepakati jalur komunikasi menjaga proyek bersama tetap berjalan. Berhenti menunggu atau mengabaikan mitra merusak kerja sama."},
{a:"jejaring", q:"Seorang rekan senior enggan berbagi arsip dan pengalamannya karena merasa nanti Anda akan menyaingi dirinya. Yang Anda lakukan...", o:[["Menghargai pengalamannya, meminta bimbingan dengan rendah hati, dan menawarkan membantu pekerjaannya sebagai timbal balik",5],["Mendekati beliau dengan sopan, meminta saran secara bertahap, dan menunjukkan bahwa Anda ingin belajar demi kemajuan tim",4],["Mencari arsip sendiri tanpa melibatkannya",3],["Mengeluhkan sikapnya kepada rekan lain",2],["Mengambil arsipnya tanpa izin",1]], p:"Pendekatan rendah hati dan timbal balik membangun kepercayaan. Mengeluh atau mengambil tanpa izin merusak hubungan."},
{a:"jejaring", q:"Setelah proyek bersama mitra eksternal selesai, tidak ada lagi alasan resmi untuk berkomunikasi dengan mereka. Sikap Anda...", o:[["Mengucapkan terima kasih, menyimpan kontak, lalu mengabari mereka secara berkala tentang peluang kerja sama baru",5],["Mengirim ucapan terima kasih dan laporan hasil proyek kepada mitra serta menyimpan kontak mereka untuk keperluan mendatang",4],["Menghubungi mereka hanya jika ada keperluan",3],["Menghapus kontak karena proyek sudah selesai",2],["Melupakan mitra yang tidak lagi menguntungkan",1]], p:"Jaringan perlu dirawat, bukan hanya dipakai saat butuh. Memutus hubungan setelah proyek merugikan peluang kerja sama berikutnya."},
{a:"jejaring", q:"Tim Anda mendapat penghargaan, padahal bantuan unit lain berperan besar dalam keberhasilan itu. Yang Anda lakukan...", o:[["Menyebut kontribusi unit lain saat menerima penghargaan dan mengajak mereka merayakannya",5],["Mengucapkan terima kasih kepada unit yang membantu dalam sambutan, lalu menyampaikan kabar baik itu kepada seluruh pimpinan mereka",4],["Menyebut tim sendiri saja karena penghargaan atas nama tim",3],["Diam saja agar tidak memperpanjang cerita",2],["Mengklaim seluruh keberhasilan sebagai hasil kerja tim Anda",1]], p:"Mengakui kontribusi pihak lain memperkuat kepercayaan lintas unit. Mengklaim sendiri merusak hubungan kerja."},
{a:"jejaring", q:"Anda berbeda pendapat dengan instansi mitra soal jadwal kegiatan bersama yang sudah hampir dekat. Sikap Anda...", o:[["Mengajak berdiskusi, memaparkan alasan masing-masing, lalu menyepakati jadwal kompromi yang menguntungkan kedua pihak",5],["Meminta pertemuan singkat untuk membahas kendala jadwal masing-masing sambil mencari beberapa pilihan tanggal pengganti yang memungkinkan",4],["Mengikuti jadwal mereka agar tidak ribut",3],["Menunggu mereka mengubah jadwal sendiri",2],["Mengancam membatalkan kerja sama jika tidak sesuai",1]], p:"Diskusi dan kompromi menjaga kemitraan tetap sehat. Menurut tanpa diskusi atau mengancam tidak menyelesaikan perbedaan."},
{a:"sosbud", q:"Tetangga baru Anda berasal dari daerah lain dan bahasanya sulit dipahami warga sekitar sehingga ia cenderung menyendiri. Yang Anda lakukan...", o:[["Menyapa, mengajaknya ikut kegiatan warga, dan belajar beberapa kata bahasanya sebagai bentuk keakraban",5],["Mengunjungi dan memperkenalkan diri dengan ramah, lalu menjelaskan kebiasaan penting di lingkungan agar ia cepat beradaptasi dengan nyaman",4],["Menyapa jika kebetulan bertemu",3],["Membiarkan sampai ia mendekat lebih dulu",2],["Menggunjingkan logat bicaranya bersama warga",1]], p:"Menyambut dan melibatkan pendatang membangun kebersamaan. Membiarkan atau menggunjing menumbuhkan jarak sosial."},
{a:"sosbud", q:"Dalam rapat kantor, rekan Anda berbicara dengan logat daerah yang kental dan beberapa orang menertawakannya. Sikap Anda...", o:[["Mengingatkan dengan sopan bahwa logat adalah kekayaan budaya, lalu menanggapi isi pendapatnya dengan serius",5],["Menegur halus rekan yang tertawa setelah rapat, dan menyatakan dukungan kepada rekan yang berbicara itu secara pribadi",4],["Diam saja karena tidak ikut tertawa",3],["Ikut tersenyum agar suasana akrab",2],["Ikut menertawakan dan menirukan logatnya",1]], p:"Menghargai keberagaman berarti membela rekan dari ejekan dan fokus pada isi pendapat. Ikut menertawakan adalah perundungan budaya."},
{a:"sosbud", q:"Anda menjadi panitia acara kantor dan salah seorang rekan memiliki pantangan makanan karena keyakinannya. Yang Anda lakukan...", o:[["Menanyakan pantangan semua peserta di awal dan memastikan menu tersedia bagi setiap kelompok",5],["Menyiapkan menu khusus untuk rekan tersebut dan memberi tahu bahwa makanan itu sudah disesuaikan dengan kebutuhannya",4],["Menyediakan menu umum saja dan membiarkan rekan memilih",3],["Menyarankan rekan membawa makanan sendiri",2],["Menganggap pantangan itu merepotkan panitia",1]], p:"Mengantisipasi kebutuhan semua peserta menunjukkan toleransi yang inklusif. Menganggap merepotkan berarti tidak menghargai perbedaan."},
{a:"sosbud", q:"Pada hari tertentu, seorang rekan dari daerah lain datang ke kantor mengenakan busana adat dan sebagian orang memandanginya dengan heran. Sikap Anda...", o:[["Memuji dengan tulus, menanyakan makna busananya, lalu mengajak rekan lain mengenal budaya tersebut",5],["Menyapa dan menyampaikan bahwa busananya indah, kemudian meminta ia bercerita tentang adat asalnya saat istirahat siang",4],["Menganggap itu urusan pribadinya",3],["Ikut memandangi dengan heran",2],["Menyindir bahwa busananya tidak cocok untuk kantor",1]], p:"Menghargai ekspresi budaya sekaligus mengajak belajar memperkaya persatuan. Menyindir adalah sikap tidak toleran."},
{a:"sosbud", q:"Beredar isu di kampung bahwa warga pendatang yang baru tinggal membawa masalah, padahal belum ada bukti sama sekali. Yang Anda lakukan...", o:[["Meluruskan isu, mengajak warga mengenal pendatang, lalu mengusulkan pertemuan warga untuk saling berkenalan",5],["Mengingatkan warga agar tidak menyebarkan isu tanpa bukti, dan menyarankan semua pihak bertemu langsung untuk saling mengenal",4],["Tidak ikut campur dalam pembicaraan itu",3],["Menunggu isu mereda sendiri",2],["Ikut menyebarkan isu agar warga waspada",1]], p:"Meluruskan prasangka dan mempertemukan warga mencegah perpecahan. Ikut menyebar isu merusak kerukunan."},
{a:"sosbud", q:"Pada hari besar keagamaan salah seorang rekan, Anda mendapat giliran piket yang bentrok dengan acara rekan tersebut. Sikap Anda...", o:[["Menawarkan bertukar jadwal piket agar rekan bisa beribadah, lalu memberi tahu atasan perubahan tersebut",5],["Menawarkan menggantikan piket rekan itu dengan syarat ia membantu Anda pada hari libur nasional berikutnya yang akan datang",4],["Mengikuti jadwal yang sudah ditetapkan",3],["Meminta rekan mencari pengganti sendiri",2],["Menyarankan rekan mengabaikan ibadahnya demi tugas",1]], p:"Saling menghargai ibadah dengan solusi jadwal yang tertib menunjukkan toleransi. Meminta mengabaikan ibadah melanggar hak beribadah."},
{a:"sosbud", q:"Panitia lomba tujuh belasan di kampung tidak mengajak warga dari kelompok minoritas karena merasa mereka tidak akan berminat. Yang Anda lakukan...", o:[["Mengusulkan mengundang semua warga, mendatangi mereka langsung, lalu memastikan lomba dapat diikuti siapa pun",5],["Menyampaikan kepada panitia bahwa lomba kemerdekaan milik seluruh warga, kemudian menyarankan undangan terbuka bagi semua keluarga di kampung",4],["Menunggu mereka mendaftar sendiri",3],["Menyetujui keputusan panitia agar tidak berdebat",2],["Mendukung agar mereka tidak diikutkan",1]], p:"Persatuan terwujud ketika semua warga dilibatkan secara aktif. Setuju atau mendukung pengucilan adalah diskriminasi."},
{a:"sosbud", q:"Saat penyuluhan di desa adat, Anda diberi tahu bahwa ada area yang tidak boleh dimasuki tanpa izin tokoh adat. Sikap Anda...", o:[["Meminta izin kepada tokoh adat, mengikuti tata caranya, lalu menyesuaikan jadwal penyuluhan dengan aturan setempat",5],["Menghormati larangan itu dan menyelenggarakan penyuluhan di tempat lain yang disepakati bersama perangkat desa setempat",4],["Masuk sebentar saja karena hanya sebentar",3],["Menganggap larangan itu takhayul sehingga tidak perlu dipatuhi",2],["Masuk tanpa izin karena tugas lebih penting",1]], p:"Menghormati adat setempat dengan izin dan penyesuaian memudahkan tugas dan menjaga hubungan. Melanggar larangan adat menimbulkan konflik."},
{a:"sosbud", q:"Seorang teman lama sering bercanda dengan ejekan tentang suku salah seorang teman lain dalam kelompok Anda. Yang Anda lakukan...", o:[["Menegur dengan tenang bahwa ejekan suku menyakitkan, lalu mengajak semua bercanda tanpa menyinggung latar belakang",5],["Menegur teman itu secara pribadi agar tidak mengulangi, kemudian meminta maaf kepada teman yang disinggung atas nama kelompok",4],["Diam karena sekadar bercanda",3],["Mengalihkan topik pembicaraan tanpa membahasnya",2],["Ikut tertawa agar tidak dianggap kaku",1]], p:"Menegur ejekan SARA dengan santun menjaga lingkungan yang saling menghormati. Diam atau ikut tertawa membiarkan diskriminasi berlangsung."},
{a:"sosbud", q:"Warga mengadakan kerja bakti pada hari libur dan Anda yang baru pindah belum mengenal siapa pun di lingkungan itu. Sikap Anda...", o:[["Ikut hadir, memperkenalkan diri, dan membantu pekerjaan sambil berbincang dengan warga",5],["Hadir membawa minuman untuk warga dan ikut membantu membersihkan lingkungan sambil memperkenalkan diri kepada pengurus lingkungan",4],["Menitipkan uang iuran tanpa hadir",3],["Tetap di rumah karena belum kenal siapa pun",2],["Menganggap kerja bakti bukan urusan pendatang",1]], p:"Hadir langsung mempercepat pembauran dengan warga. Menitip atau menjauh menghambat adaptasi sosial."},
{a:"sosbud", q:"Rekan difabel di kantor kesulitan mengikuti acara outing karena lokasinya tidak ramah akses. Yang Anda lakukan...", o:[["Mengusulkan lokasi yang dapat diakses semua rekan, lalu memastikan transportasi dan fasilitasnya sebelum acara",5],["Mengusulkan agar panitia mengubah rute kegiatan menjadi lebih mudah diakses dan bertanya langsung kepada rekan itu tentang kebutuhannya",4],["Menyarankan rekan itu ikut sebisanya",3],["Membiarkan ia tidak ikut karena kendalanya jelas",2],["Mengatakan bahwa acara tidak harus diikuti semua orang",1]], p:"Inklusivitas berarti merancang kegiatan agar semua rekan dapat ikut. Membiarkan tidak ikut atau meremehkan adalah diskriminasi."},
{a:"sosbud", q:"Rekan dari daerah lain makan dengan tangan di kantin sesuai kebiasaannya, dan beberapa orang menjauh dengan jijik. Sikap Anda...", o:[["Duduk bersamanya, menjelaskan kepada yang lain bahwa itu kebiasaan budaya, dan mengajak mereka makan bersama",5],["Menghampiri rekan itu dan menemaninya makan, lalu menegur dengan halus rekan yang menjauh bahwa kebiasaan itu perlu dihargai",4],["Membiarkan karena masing-masing punya kebiasaan",3],["Ikut menjauh agar tidak dianggap aneh",2],["Menyuruh rekan itu mengikuti kebiasaan kantor",1]], p:"Hadir mendampingi dan memberi pemahaman menumbuhkan penerimaan antarbudaya. Ikut menjauh atau memaksa seragam tidak menghargai keberagaman."},
{a:"sosbud", q:"Tetangga Anda menggelar pesta pernikahan dengan tradisi adat yang asing bagi Anda, termasuk aturan memberi sumbangan khusus. Yang Anda lakukan...", o:[["Hadir, menghormati tata cara adat, dan menanyakan kepada warga sekitar kebiasaan yang perlu diikuti",5],["Hadir dengan pakaian yang sopan dan mengikuti kebiasaan yang berlaku sambil bertanya kepada tetangga jika ada hal yang kurang dipahami",4],["Hadir sebentar lalu pulang karena merasa asing",3],["Tidak hadir karena adat itu tidak Anda pahami",2],["Mengkritik adat itu di depan warga",1]], p:"Hadir dan belajar tata cara adat menunjukkan penghargaan pada budaya setempat. Menghindari atau mengkritik merusak kerukunan."},
{a:"sosbud", q:"Dua kelompok warga berselisih karena pandangan berbeda soal pemilihan kepala desa dan hampir saling memboikot di lingkungan. Sikap Anda...", o:[["Mengajak tokoh warga memediasi, menekankan kebersamaan, dan mengusulkan kegiatan bersama yang melibatkan kedua kelompok",5],["Mengajak kedua kelompok berdialog di balai desa dengan didampingi tokoh masyarakat agar perbedaan tidak berubah menjadi permusuhan",4],["Menjauhi keduanya agar tidak terlibat",3],["Mendukung kelompok yang sepandangan dengan Anda",2],["Menyebarkan keburukan kelompok lawan",1]], p:"Mediasi yang menekankan persatuan mencegah perpecahan. Berpihak atau menyebar keburukan memperbesar konflik."},
{a:"sosbud", q:"Sebagai penyuluh, Anda menghadapi warga yang menolak pembangunan fasilitas umum karena dianggap melanggar kebiasaan leluhur mereka. Yang Anda lakukan...", o:[["Mendengarkan alasan mereka, melibatkan tokoh adat, lalu mencari rancangan yang tetap menghormati kebiasaan setempat",5],["Menjelaskan manfaat fasilitas tersebut dengan bahasa yang mudah dan melibatkan tokoh adat dalam pembicaraan tentang lokasi pembangunannya",4],["Meneruskan keberatan itu kepada atasan",3],["Menunda penyuluhan sampai warga berubah pikiran",2],["Tetap membangun dengan alasan kepentingan umum",1]], p:"Dialog dan pelibatan tokoh adat menggabungkan kepentingan umum dengan penghormatan budaya. Memaksa atau melempar masalah tidak menyelesaikan penolakan."},
{a:"sosbud", q:"Anda ditugaskan di sekolah yang siswanya berasal dari beragam latar belakang, dan saat kelompok belajar dibentuk, siswa cenderung memilih teman sedaerah saja. Yang Anda lakukan...", o:[["Mengatur kelompok campuran, menjelaskan manfaat belajar bersama teman berbeda latar belakang, lalu memantau kerja sama mereka",5],["Membentuk kelompok dengan anggota dari berbagai daerah dan meminta tiap kelompok berbagi cerita budaya asalnya pada awal pertemuan kelas",4],["Membiarkan siswa memilih kelompok sesuai kenyamanannya",3],["Menyerahkan pembentukan kelompok kepada ketua kelas",2],["Membenarkan pemisahan kelompok karena lebih praktis",1]], p:"Kelompok campuran melatih siswa menghargai perbedaan dan membangun persatuan. Membiarkan atau membenarkan pemisahan memperkuat sekat antarkelompok."},
{a:"tik", q:"Anda menerima email berisi tautan hadiah undian yang meminta Anda mengisi data pribadi dan kata sandi. Yang Anda lakukan...", o:[["Tidak mengeklik, menghapus email itu, lalu melaporkannya kepada petugas keamanan siber dan memperingatkan rekan",5],["Tidak mengeklik tautan itu dan menandainya sebagai spam agar tidak muncul lagi di kotak masuk Anda",4],["Mengeklik tautan untuk memeriksa tetapi tidak mengisi data",3],["Mengisi data karena hadiahnya menarik",2],["Meneruskan email itu ke banyak orang agar mereka ikut menang",1]], p:"Menghindari tautan mencurigakan dan melaporkannya melindungi seluruh organisasi. Mengeklik atau menyebarkan membuka celah penipuan."},
{a:"tik", q:"Seorang rekan mengajak berbagi satu akun aplikasi kantor dengan kata sandi yang sama agar tidak perlu mendaftar lagi. Sikap Anda...", o:[["Menolak berbagi, membuat akun sendiri, dan menyarankan rekan juga menggunakan akun pribadi demi keamanan",5],["Menolak dengan sopan dan menjelaskan bahwa kata sandi bersifat rahasia dan harus digunakan oleh pemiliknya saja",4],["Setuju asalkan kata sandi diganti secara berkala",3],["Setuju agar pekerjaan lebih praktis",2],["Menuliskan kata sandi di kertas dan menempelkannya di meja",1]], p:"Akun pribadi menjamin jejak aktivitas dan keamanan data. Berbagi kata sandi melanggar kebijakan keamanan informasi."},
{a:"tik", q:"Muncul berita viral di media sosial tentang bencana di suatu daerah, tetapi Anda ragu apakah isinya benar. Yang Anda lakukan...", o:[["Mengecek sumber resmi dan situs cek fakta, lalu membagikan klarifikasi jika berita itu terbukti keliru",5],["Menunggu informasi dari lembaga resmi sebelum membagikan apa pun, dan memberi tahu keluarga agar tidak langsung percaya pada berita viral itu",4],["Membaca beritanya tanpa membagikan",3],["Membagikan berita itu dengan keterangan semoga tidak benar",2],["Membagikan segera agar orang waspada",1]], p:"Memeriksa fakta dan membagikan klarifikasi mencegah hoaks meluas. Menyebar berita yang belum jelas memicu kepanikan."},
{a:"tik", q:"Kantor Anda memberlakukan sistem arsip digital baru, dan Anda merasa kesulitan karena terbiasa dengan arsip kertas. Sikap Anda...", o:[["Mengikuti pelatihan, berlatih di luar jam sibuk, dan meminta bimbingan rekan yang lebih mahir",5],["Mempelajari panduan penggunaan sistem itu sedikit demi sedikit sambil mencatat bagian yang masih membingungkan untuk ditanyakan kepada petugas",4],["Tetap memakai arsip kertas bersama sistem baru",3],["Menunggu rekan lain mengerjakan bagian digital",2],["Menolak memakai sistem karena merepotkan",1]], p:"Mau belajar dan mencari bimbingan mempercepat adaptasi teknologi. Menolak atau menyerahkan tugas membuat Anda tertinggal."},
{a:"tik", q:"Di area parkir kantor, Anda menemukan flashdisk tergeletak tanpa pemilik yang jelas. Yang Anda lakukan...", o:[["Tidak menancapkannya ke komputer, menyerahkannya kepada petugas TI untuk diperiksa, dan mengumumkan penemuan itu",5],["Menyerahkannya kepada bagian keamanan agar dicari pemiliknya tanpa membuka isi flashdisk tersebut di komputer kantor",4],["Menyimpannya di laci sampai ada yang mencari",3],["Menancapkannya ke komputer untuk mencari identitas pemilik",2],["Membawanya pulang untuk dipakai sendiri",1]], p:"Perangkat asing bisa membawa virus, sehingga penanganan oleh petugas TI paling aman. Menancapkan sendiri membahayakan jaringan kantor."},
{a:"tik", q:"Rekan Anda mengunggah foto dokumen internal kantor di media sosial pribadinya karena dikira tidak penting. Sikap Anda...", o:[["Menegur dengan sopan, meminta fotonya dihapus, lalu menjelaskan aturan kerahasiaan dokumen kepada seluruh tim",5],["Menyampaikan kepada rekan itu secara pribadi bahwa dokumen internal tidak boleh dipublikasikan dan meminta unggahan itu segera dihapus",4],["Melaporkan langsung kepada atasan tanpa menegur dulu",3],["Mengabaikan karena itu akun pribadinya",2],["Ikut membagikan unggahan itu ke grup lain",1]], p:"Menegur dan mengedukasi menjaga kerahasiaan informasi sekaligus hubungan baik. Mengabaikan atau menyebarkan membahayakan data kantor."},
{a:"tik", q:"Anda perlu mengakses sistem kantor saat bepergian dan hanya tersedia jaringan wifi umum di sebuah kafe. Yang Anda lakukan...", o:[["Menggunakan data seluler atau jaringan pribadi yang aman, dan menunda akses jika tidak memungkinkan",5],["Memakai wifi kafe dengan jaringan privat virtual yang disediakan kantor agar lalu lintas data tetap terenkripsi dan terlindungi",4],["Memakai wifi kafe untuk membuka dokumen yang tidak rahasia saja",3],["Memakai wifi kafe karena gratis dan cepat",2],["Menyebarkan kata sandi sistem kantor kepada pengunjung kafe",1]], p:"Jaringan publik rawan penyadapan, sehingga jaringan pribadi yang aman lebih baik. Memakai wifi terbuka tanpa perlindungan membahayakan data kantor."},
{a:"tik", q:"Anda rutin menyusun laporan mingguan secara manual selama berjam-jam, padahal sebagian proses dapat diotomasi dengan lembar kerja digital. Sikap Anda...", o:[["Mempelajari fitur otomasi, membuat templat, lalu membagikannya kepada rekan agar pekerjaan semua orang lebih efisien",5],["Mencari tutorial fitur lembar kerja yang bisa mempercepat penyusunan laporan lalu mencobanya pada laporan minggu depan dengan teliti",4],["Tetap bekerja manual karena sudah terbiasa",3],["Menunggu atasan menyediakan aplikasi khusus",2],["Menyerahkan tugas laporan kepada rekan yang lebih paham",1]], p:"Memanfaatkan TIK untuk efisiensi dan membagikannya membawa manfaat lebih luas. Bertahan dengan cara lama atau melempar tugas menghambat produktivitas."},
{a:"tik", q:"Akun media sosial resmi instansi Anda menerima komentar kasar dari warga yang kecewa dengan sebuah layanan. Yang Anda lakukan...", o:[["Menanggapi dengan sopan, meminta detail masalahnya secara pribadi, lalu menindaklanjuti dan mengabarkan hasilnya kepada warga tersebut",5],["Membalas dengan ramah dan meminta maaf atas ketidaknyamanan, lalu menyarankan warga menghubungi nomor layanan pengaduan resmi",4],["Membiarkan komentar itu tanpa menjawab",3],["Menghapus komentar agar tidak dibaca orang lain",2],["Membalas dengan komentar yang tak kalah kasar",1]], p:"Etika bermedia sosial menuntut tanggapan santun dan tindak lanjut nyata. Menghapus atau membalas kasar merusak kepercayaan publik."},
{a:"tik", q:"Dalam rapat daring, Anda membagikan layar dan baru sadar notifikasi pesan pribadi muncul di layar yang dilihat semua peserta. Sikap Anda...", o:[["Segera menghentikan berbagi layar, meminta maaf singkat, dan mulai membiasakan mematikan notifikasi sebelum rapat",5],["Menutup jendela pesan itu dengan cepat dan melanjutkan rapat, lalu memeriksa pengaturan notifikasi setelah rapat berakhir nanti",4],["Melanjutkan rapat seolah tidak terjadi apa-apa",3],["Menyalahkan aplikasi yang menampilkan notifikasi",2],["Menyalahkan peserta yang membaca pesan itu",1]], p:"Menanggapi cepat dan membenahi kebiasaan mencegah kebocoran privasi berulang. Menyalahkan pihak lain tidak bertanggung jawab."},
{a:"tik", q:"Selama ini Anda tidak pernah mencadangkan berkas pekerjaan penting, padahal komputer kantor sudah sering lambat dan berpotensi rusak. Yang Anda lakukan...", o:[["Segera mencadangkan ke penyimpanan resmi kantor, lalu membuat jadwal pencadangan rutin dan mengajak rekan melakukannya",5],["Menyalin berkas penting ke penyimpanan awan yang disediakan kantor, lalu memeriksa bahwa semua berkas dapat dibuka kembali dengan baik",4],["Mencadangkan kalau sempat saja",3],["Menunggu sampai komputer benar-benar bermasalah",2],["Menganggap pencadangan itu buang waktu",1]], p:"Pencadangan rutin melindungi pekerjaan dari kehilangan data. Menunda hingga rusak sering berakhir pada kerugian besar."},
{a:"tik", q:"Grup keluarga Anda ramai membagikan pesan berantai tentang pengobatan tertentu yang diklaim menyembuhkan semua penyakit. Sikap Anda...", o:[["Menelusuri kebenarannya di sumber kesehatan resmi, lalu membagikan klarifikasi dengan bahasa santun kepada seluruh anggota grup",5],["Menyarankan keluarga menanyakan kepada tenaga kesehatan sebelum mempercayai pesan berantai, serta tidak membagikannya lagi ke grup lain",4],["Tidak membagikan lagi tetapi juga tidak menanggapi",3],["Ikut meneruskan karena banyak yang sudah membagikan",2],["Mengejek anggota keluarga yang membagikannya",1]], p:"Mengecek fakta dan mengedukasi keluarga menekan hoaks dengan cara baik. Meneruskan atau mengejek tidak menyelesaikan masalah."},
{a:"tik", q:"Aplikasi pelaporan warga yang Anda kelola sering error pada jam sibuk dan banyak pengguna mengeluh. Yang Anda lakukan...", o:[["Mencatat pola error, melaporkannya kepada tim teknis dengan data jelas, dan menyiapkan jalur laporan sementara bagi warga",5],["Menyampaikan keluhan pengguna kepada tim teknis beserta waktu terjadinya error agar mudah dilacak dan segera diperbaiki dengan cepat",4],["Menyarankan warga mencoba lagi nanti",3],["Menunggu tim teknis menyadari sendiri masalahnya",2],["Mengatakan bahwa aplikasi itu memang bermasalah",1]], p:"Data konkret dan solusi sementara menjaga layanan tetap berjalan. Menunggu atau pasrah membuat warga terus dirugikan."},
{a:"tik", q:"Rekan senior yang sebentar lagi pensiun kesulitan memakai aplikasi perkantoran daring dan sering tertinggal informasi. Sikap Anda...", o:[["Mendampingi dengan sabar, membuat panduan langkah demi langkah, dan menyediakan waktu latihan rutin bersamanya",5],["Menunjukkan cara memakai fitur dasar aplikasi dengan sabar dan menawarkan bantuan kapan pun ia mengalami kesulitan di kemudian hari",4],["Mengirimkan tautan tutorial kepadanya",3],["Mengerjakan sendiri bagian digitalnya tanpa mengajarinya",2],["Menertawakan ketidakmampuannya di depan rekan lain",1]], p:"Pendampingan sabar menumbuhkan literasi digital seluruh tim. Mengerjakan sendiri atau menertawakan tidak membantu dan merendahkan."},
{a:"tik", q:"Di akun pribadi, Anda ingin menyampaikan pendapat tentang kebijakan instansi yang menurut Anda kurang tepat. Yang Anda lakukan...", o:[["Menyampaikan masukan lewat jalur internal yang resmi, dan tidak membahas hal internal secara terbuka di media sosial",5],["Menulis opini tanpa menyebut data internal atau instansi, dengan bahasa santun dan tidak menyerang pihak tertentu secara pribadi",4],["Membahasnya di grup pertemanan tertutup saja",3],["Menyindir kebijakan itu tanpa menyebut nama",2],["Mengunggah dokumen internal sebagai bukti kritik Anda",1]], p:"Jalur resmi menjaga kritik tetap konstruktif dan menjaga nama baik instansi. Menyindir atau membocorkan dokumen melanggar etika dan aturan."},
{a:"tik", q:"Laptop kantor Anda menampilkan pemberitahuan pembaruan keamanan yang mengharuskan komputer dimulai ulang di tengah pekerjaan. Sikap Anda...", o:[["Menyimpan pekerjaan, menjadwalkan pembaruan di waktu senggang dalam hari itu, lalu memastikan pembaruan selesai dilakukan",5],["Menunda pembaruan sampai istirahat siang, lalu menjalankannya agar sistem Anda terlindungi dari celah keamanan terbaru yang diketahui",4],["Menunda terus sampai tidak ada pekerjaan mendesak",3],["Menutup pemberitahuan setiap kali muncul",2],["Mematikan fitur pembaruan agar tidak mengganggu",1]], p:"Pembaruan keamanan menutup celah serangan sehingga perlu dijadwalkan dan dituntaskan. Menunda tanpa batas atau mematikannya membahayakan sistem."},
{a:"profesional", q:"Setelah laporan keuangan Anda diterima atasan, Anda menemukan kesalahan hitung yang belum disadari siapa pun. Yang Anda lakukan...", o:[["Segera melapor kepada atasan, memperbaiki perhitungan, dan menyusun pemeriksaan ganda agar tidak terulang",5],["Menghubungi atasan, menjelaskan kesalahan itu dengan jujur, lalu mengirim laporan revisi yang sudah diperiksa ulang sebelum jam kerja berakhir",4],["Memperbaikinya diam-diam tanpa memberi tahu siapa pun",3],["Menunggu sampai ada yang menyadari kesalahan itu",2],["Membiarkannya karena laporan sudah diterima",1]], p:"Kejujuran dan perbaikan segera mencerminkan integritas dan tanggung jawab. Menyembunyikan atau membiarkan kesalahan berisiko merugikan organisasi."},
{a:"profesional", q:"Hari ini Anda memiliki dua tugas yang sama-sama mendesak dari dua atasan yang berbeda dan tidak mungkin selesai bersamaan. Sikap Anda...", o:[["Menjelaskan beban kerja kepada kedua atasan, meminta kesepakatan prioritas, lalu mengerjakan sesuai urutan yang disepakati",5],["Menilai tenggat dan dampak masing-masing tugas, lalu mengerjakan yang paling mendesak sambil memberi kabar kepada atasan lainnya",4],["Mengerjakan keduanya sekaligus dengan kualitas seadanya",3],["Mengerjakan tugas atasan yang lebih galak lebih dulu",2],["Mengabaikan salah satu tugas tanpa kabar",1]], p:"Komunikasi prioritas membuat pekerjaan terukur dan kualitas terjaga. Mengerjakan seadanya atau mengabaikan tugas merugikan tim."},
{a:"profesional", q:"Seorang rekanan proyek mengirimkan bingkisan mahal ke meja Anda menjelang pengumuman pemenang pengadaan. Yang Anda lakukan...", o:[["Menolak dan mengembalikan bingkisan, mencatatnya, lalu melaporkan kepada unit pengendali gratifikasi",5],["Mengembalikan bingkisan itu dengan sopan disertai penjelasan bahwa pegawai tidak boleh menerima pemberian dari rekanan",4],["Menyimpan dulu sambil menunggu keputusan atasan",3],["Menerima karena sulit menolak pemberian orang",2],["Menerima dan berjanji membantu rekanan tersebut",1]], p:"Pemberian dari rekanan menjelang keputusan adalah gratifikasi yang harus ditolak dan dilaporkan. Menerima dalam bentuk apa pun merusak integritas."},
{a:"profesional", q:"Atasan mengkritik hasil kerja Anda yang menurut Anda sudah baik, dan mengatakan format laporan perlu diperbaiki. Sikap Anda...", o:[["Mendengarkan, meminta contoh format yang diinginkan, lalu memperbaiki laporan dan berterima kasih atas masukannya",5],["Menerima masukan dengan tenang, memperbaiki laporan sesuai arahan, dan memeriksa kembali agar kesalahan serupa tidak muncul pada laporan berikutnya",4],["Memperbaiki laporan sambil merasa tidak setuju",3],["Menjelaskan panjang lebar bahwa laporan sudah benar",2],["Menolak memperbaiki karena merasa sudah benar",1]], p:"Kritik adalah bahan pengembangan diri, sehingga diterima dan ditindaklanjuti. Membantah atau menolak menunjukkan sikap kurang profesional."},
{a:"profesional", q:"Beberapa kali dalam sebulan Anda datang terlambat karena kemacetan yang makin parah di jalur berangkat Anda. Yang Anda lakukan...", o:[["Berangkat lebih awal, mencari jalur alternatif, dan meminta maaf kepada atasan sambil berkomitmen tepat waktu",5],["Mengatur ulang jadwal pagi dan berangkat lebih awal, lalu menyampaikan kepada atasan bahwa Anda sedang memperbaiki kedisiplinan",4],["Menyampaikan alasan macet setiap kali terlambat",3],["Meminta rekan mengisi daftar hadir lebih dulu",2],["Menganggap terlambat wajar karena macet bukan salah Anda",1]], p:"Disiplin berarti mencari solusi atas hambatan yang bisa diantisipasi. Memberi alasan terus atau memanipulasi kehadiran melanggar aturan."},
{a:"profesional", q:"Seorang rekan meminta Anda meminjamkan stempel unit dan membubuhkan tanda tangan atasan karena atasan sedang di luar kota dan surat mendesak. Sikap Anda...", o:[["Menolak, menghubungi atasan untuk meminta persetujuan resmi, lalu mengikuti prosedur tanda tangan yang berlaku",5],["Menolak dengan sopan dan menyarankan rekan menghubungi atasan lewat telepon agar mendapat persetujuan tertulis sebelum surat dikirimkan",4],["Menyerahkan stempel tetapi tidak ikut menandatangani",3],["Membantu karena rekan itu sedang terdesak",2],["Menandatangani sendiri atas nama atasan",1]], p:"Tanda tangan dan stempel adalah kewenangan yang tidak boleh dipalsukan walau mendesak. Memalsukan adalah pelanggaran berat."},
{a:"profesional", q:"Ada kesempatan kursus peningkatan keterampilan yang relevan dengan pekerjaan Anda, tetapi pendaftarannya harus dilakukan secara mandiri. Yang Anda lakukan...", o:[["Mendaftar, mengatur jadwal agar pekerjaan tidak terganggu, lalu membagikan ilmunya kepada rekan setelah selesai",5],["Mendaftar dan mengikuti kursus dengan sungguh-sungguh, lalu menerapkan ilmu yang didapat dalam pekerjaan sehari-hari secara bertahap",4],["Mempertimbangkan dulu sambil menunggu penawaran dari kantor",3],["Menunda karena merasa sudah cukup mampu",2],["Menolak karena tidak ada kewajiban",1]], p:"Pengembangan diri secara mandiri dan berbagi ilmu menaikkan kualitas organisasi. Menunggu atau menolak membuat kompetensi stagnan."},
{a:"profesional", q:"Di akhir tahun anggaran masih ada sisa dana, dan atasan menyuruh menghabiskannya untuk membeli barang yang sebenarnya tidak dibutuhkan. Sikap Anda...", o:[["Menyampaikan dengan sopan bahwa pembelian harus sesuai kebutuhan, lalu mengusulkan pengembalian sisa dana atau penggunaan yang bermanfaat",5],["Mengajukan usulan barang yang benar-benar dibutuhkan unit dan sesuai ketentuan, disertai alasan yang dapat dipertanggungjawabkan kepada atasan",4],["Melaksanakan perintah karena itu keputusan atasan",3],["Membeli barang lalu mencatat sekenanya",2],["Menggelembungkan harga agar sisa dana terserap",1]], p:"Anggaran adalah uang publik yang harus digunakan sesuai kebutuhan dan dapat dipertanggungjawabkan. Menurut tanpa pertimbangan atau memanipulasi adalah pelanggaran."},
{a:"profesional", q:"Anda menemukan dokumen berklasifikasi rahasia tertinggal di meja rekan setelah jam kerja berakhir. Yang Anda lakukan...", o:[["Mengamankannya di tempat penyimpanan, memberi tahu pemiliknya dan atasan, lalu mengingatkan pentingnya mengamankan dokumen",5],["Menyimpannya di lemari terkunci dan mengabari rekan tersebut agar mengambilnya besok pagi di bagian yang aman",4],["Membiarkannya karena itu tanggung jawab pemilik",3],["Membaca isinya karena penasaran",2],["Memfoto dokumen untuk keperluan pribadi",1]], p:"Mengamankan dan melaporkan dokumen rahasia menjaga kepercayaan organisasi. Membiarkan atau membaca tanpa hak adalah pelanggaran."},
{a:"profesional", q:"Anda menjadi panitia pengadaan dan salah satu peserta lelang ternyata kerabat dekat Anda. Sikap Anda...", o:[["Menyatakan benturan kepentingan kepada atasan dan mengundurkan diri dari proses penilaian peserta tersebut",5],["Melaporkan hubungan kekerabatan itu kepada atasan dan membiarkan panitia lain yang menilai penawaran peserta itu secara objektif",4],["Tetap menilai secara jujur tanpa memberi tahu siapa pun",3],["Memberi bocoran kecil kepada kerabat tanpa merugikan peserta lain",2],["Memenangkan kerabat agar keluarga terbantu",1]], p:"Benturan kepentingan wajib diungkapkan dan dihindari demi objektivitas. Menyembunyikan atau memihak melanggar integritas."},
{a:"profesional", q:"Target kerja bulan ini tidak tercapai karena Anda sempat sakit beberapa hari dan pekerjaan menumpuk. Yang Anda lakukan...", o:[["Menjelaskan kondisi kepada atasan, menyusun rencana kejar target, dan bekerja lebih terfokus untuk menyelesaikannya",5],["Melapor jujur kepada atasan lalu meminta tambahan waktu yang wajar sambil menyusun jadwal kerja yang lebih realistis",4],["Mengerjakan seadanya agar target terlihat tercapai",3],["Menunggu atasan menanyakan target Anda",2],["Mengubah data laporan agar target tampak tercapai",1]], p:"Jujur dan menyusun rencana pemulihan menunjukkan tanggung jawab. Memanipulasi data atau menunggu ditanya tidak profesional."},
{a:"profesional", q:"Jam pulang sudah tiba, pekerjaan belum selesai, dan Anda juga memiliki acara keluarga malam ini. Sikap Anda...", o:[["Menilai sisa pekerjaan, menyelesaikan bagian terpenting secara efisien, dan menjadwalkan sisanya dengan memberi tahu atasan",5],["Menyelesaikan pekerjaan mendesak terlebih dahulu dan meminta izin menyelesaikan sisanya esok pagi agar acara keluarga tetap bisa dihadiri",4],["Pulang tepat waktu dan menyelesaikan besok tanpa kabar",3],["Menyerahkan sisa pekerjaan kepada rekan tanpa izin",2],["Meninggalkan pekerjaan karena acara keluarga lebih penting",1]], p:"Mengatur prioritas dan berkomunikasi menjaga tanggung jawab kerja dan keluarga. Meninggalkan atau melempar pekerjaan merugikan tim."},
{a:"profesional", q:"Aturan baru mengubah prosedur kerja unit Anda, dan beberapa rekan lama enggan mengikutinya karena merasa cara lama lebih cepat. Yang Anda lakukan...", o:[["Mempelajari aturan baru, menerapkannya, lalu membantu rekan memahami manfaat dan caranya agar semua mengikuti",5],["Mengikuti prosedur baru dan menyampaikan masukan resmi jika ada bagian yang menghambat pekerjaan, tanpa meninggalkan aturan yang berlaku",4],["Mengikuti aturan baru tetapi tidak mengajak rekan",3],["Memakai cara lama selama belum ada teguran",2],["Ikut menolak aturan bersama rekan lama",1]], p:"Taat aturan sambil membantu rekan beradaptasi menunjukkan profesionalisme. Menolak atau menunggu teguran adalah ketidakdisiplinan."},
{a:"profesional", q:"Atasan meminta Anda menandatangani laporan kegiatan yang sebagian di antaranya tidak pernah dilaksanakan agar anggaran dapat dicairkan. Sikap Anda...", o:[["Menolak menandatangani, menjelaskan risiko hukumnya secara sopan, dan melapor lewat jalur pengaduan internal jika dipaksa",5],["Menolak menandatangani dan menyarankan laporan disusun sesuai kegiatan yang benar-benar dilaksanakan agar tidak menimbulkan masalah di kemudian hari",4],["Menandatangani sambil menyampaikan keberatan secara lisan",3],["Menandatangani karena perintah atasan",2],["Menandatangani dan ikut menambahkan data fiktif",1]], p:"Laporan fiktif adalah pelanggaran hukum, sehingga harus ditolak dan dilaporkan lewat jalur tepat. Menandatangani apa pun alasannya berarti ikut bertanggung jawab."},
{a:"profesional", q:"Atasan baru Anda memiliki gaya kerja yang jauh berbeda dari atasan sebelumnya, sehingga beberapa kebiasaan kerja tim harus berubah. Yang Anda lakukan...", o:[["Memahami harapan atasan baru lewat diskusi, menyesuaikan cara kerja, dan membantu rekan melakukan hal yang sama",5],["Menanyakan prioritas dan standar kerja atasan baru, lalu menyesuaikan diri secara bertahap sambil tetap menjaga kualitas hasil kerja",4],["Menunggu instruksi atasan tanpa bertanya",3],["Tetap memakai cara kerja lama karena sudah terbukti",2],["Membandingkan atasan baru dengan atasan lama di depan rekan",1]], p:"Beradaptasi dengan komunikasi aktif menjaga kinerja tetap stabil. Membandingkan atau bertahan pada cara lama menghambat tim."},
{a:"profesional", q:"Anda ditunjuk menjadi pendamping bagi pegawai baru yang masih banyak melakukan kesalahan dalam pekerjaan hariannya. Sikap Anda...", o:[["Membimbing dengan sabar, memberi contoh kerja yang benar, dan memberi umpan balik rutin sampai ia mandiri",5],["Menjelaskan prosedur kerja dan mengoreksi kesalahannya dengan baik sambil menunjukkan cara memperbaikinya pada pekerjaan berikutnya",4],["Membiarkan ia belajar sendiri dari kesalahan",3],["Mengerjakan ulang pekerjaannya tanpa menjelaskan",2],["Memarahinya setiap kali ia melakukan kesalahan",1]], p:"Pendampingan sabar dengan umpan balik rutin menghasilkan pegawai mandiri dan berkualitas. Membiarkan atau memarahi tidak mengembangkan kemampuan."},
{a:"antiradikal", q:"Seorang kenalan mengirimkan pamflet yang mengajak menolak upacara bendera karena dianggap tidak perlu dan tidak sesuai keyakinan kelompoknya. Sikap Anda...", o:[["Tidak menyebarkan pamflet, menjelaskan makna upacara sebagai bentuk cinta tanah air, dan melaporkan jika ajakan itu terus berlanjut",5],["Tidak menyebarkan pamflet itu dan menjelaskan dengan santun bahwa menghormati bendera adalah bagian dari kesetiaan pada negara",4],["Menyimpan pamflet itu tanpa menanggapi",3],["Membiarkan karena itu urusan pribadi kenalan",2],["Ikut menyebarkan pamflet itu ke grup lain",1]], p:"Menolak ajakan yang melemahkan simbol negara sambil meluruskan dengan santun menunjukkan kesetiaan pada Pancasila dan NKRI. Membiarkan atau menyebarkan mendukung paham yang salah."},
{a:"antiradikal", q:"Dalam diskusi daring, sebuah akun anonim berulang kali menyebarkan narasi bahwa Pancasila tidak layak menjadi pedoman bangsa. Yang Anda lakukan...", o:[["Menanggapi dengan data dan bahasa santun, melaporkan akun tersebut ke platform, dan tidak ikut menyebarkan narasinya",5],["Menanggapi dengan tenang bahwa Pancasila lahir dari kesepakatan bangsa, tanpa memancing perdebatan emosional di kolom komentar",4],["Membaca saja tanpa menanggapi",3],["Menyukai komentar itu karena terdengar logis",2],["Menyerang akun tersebut dengan kata-kata kasar",1]], p:"Meluruskan dengan santun dan melapor lewat jalur platform adalah respons moderat dan bertanggung jawab. Membalas kasar atau mendukung tidak menyelesaikan masalah."},
{a:"antiradikal", q:"Anda mengetahui tetangga menyimpan selebaran yang menghalalkan kekerasan demi mencapai tujuan politik tertentu. Sikap Anda...", o:[["Tidak menyebarluaskan, mencatat yang diketahui, lalu melapor kepada ketua lingkungan atau aparat yang berwenang",5],["Mengajak bicara tetangga itu secara baik-baik tentang bahaya kekerasan, lalu menyarankan ia menghentikan penyimpanan selebaran tersebut",4],["Membiarkan karena belum ada kejadian apa pun",3],["Menceritakannya kepada banyak tetangga lain",2],["Meminta selebaran untuk ikut membaca",1]], p:"Melapor lewat jalur tepat mencegah paham kekerasan berkembang tanpa main hakim sendiri. Membiarkan atau menyebar gosip tidak membantu."},
{a:"antiradikal", q:"Seorang rekan mengajak Anda ke pertemuan tertutup kelompok tertentu yang menolak hormat kepada bendera dan menyebut pemerintah sebagai musuh. Yang Anda lakukan...", o:[["Menolak ajakan, menjelaskan alasan setia pada negara, lalu melaporkan kepada atasan atau pihak yang berwenang",5],["Menolak dengan tegas dan menyarankan rekan menjauhi kelompok yang menolak dasar negara karena berpotensi memecah persatuan bangsa",4],["Menolak tetapi tidak menceritakan kepada siapa pun",3],["Hadir sekali untuk mengetahui isi pertemuannya",2],["Bergabung agar dianggap setia kawan",1]], p:"Menolak dan melapor adalah langkah tepat menghadapi kelompok yang menentang Pancasila. Ikut hadir berisiko terpengaruh."},
{a:"antiradikal", q:"Seorang siswa di sekolah tempat Anda bertugas mengutip ucapan intoleran yang merendahkan teman sekelasnya. Sikap Anda...", o:[["Menegur dengan bijak, menjelaskan nilai persatuan dan toleransi, lalu berkoordinasi dengan guru dan orang tua untuk pembinaan",5],["Menasihati siswa itu dengan tenang agar tidak merendahkan temannya, dan meminta ia meminta maaf kepada teman yang disinggungnya",4],["Membiarkan karena masih anak-anak",3],["Menyuruhnya diam tanpa penjelasan",2],["Tertawa dan menganggapnya lucu",1]], p:"Pembinaan yang bijak bersama pihak sekolah dan keluarga menanamkan toleransi. Membiarkan atau menertawakan menormalkan intoleransi."},
{a:"antiradikal", q:"Dalam rapat warga, ada yang ingin melarang kegiatan sebagian warga lain hanya karena cara mereka berbeda dari kebanyakan. Yang Anda lakukan...", o:[["Mengingatkan bahwa semua warga berhak berkegiatan sesuai hukum, lalu mengusulkan aturan bersama yang adil dan tidak diskriminatif",5],["Menyampaikan bahwa Pancasila menjamin hak setiap warga, dan mengajak peserta rapat mencari jalan tengah yang menghargai perbedaan",4],["Memilih diam agar tidak menimbulkan perdebatan",3],["Ikut memilih melarang karena suara terbanyak",2],["Mendukung pelarangan dan mengancam warga yang keberatan",1]], p:"Prinsip keadilan dan persatuan menuntut perlindungan hak semua warga. Diam atau ikut melarang membiarkan intoleransi terjadi."},
{a:"antiradikal", q:"Anda menerima pesan berantai provokatif yang mengadu domba kelompok masyarakat dan mengajak melakukan pembalasan. Sikap Anda...", o:[["Tidak meneruskan, memeriksa kebenarannya, lalu melaporkan pesan itu ke platform atau pihak berwenang",5],["Tidak meneruskan pesan tersebut dan mengingatkan pengirim bahwa pesan itu bisa memicu perpecahan dan kekerasan di masyarakat luas",4],["Membaca lalu menghapus tanpa tindakan lain",3],["Meneruskan ke satu dua orang untuk meminta pendapat",2],["Menyebarkan ke banyak grup agar orang waspada",1]], p:"Memutus rantai pesan provokatif dan melapor mencegah konflik meluas. Meneruskan sekalipun dengan niat waspada ikut menyebar kebencian."},
{a:"antiradikal", q:"Anda diminta menjadi panitia peringatan hari lahir Pancasila di lingkungan kantor, padahal jadwal Anda sedang padat. Yang Anda lakukan...", o:[["Menerima, membagi waktu dengan baik, lalu mengusulkan kegiatan yang mengajak seluruh pegawai memahami nilai Pancasila",5],["Menerima tugas itu dan menyelesaikan bagian Anda dengan baik sambil berkoordinasi dengan panitia lain untuk pembagian pekerjaan",4],["Menerima dengan syarat tugasnya ringan",3],["Menolak karena merasa tidak punya waktu",2],["Menolak karena menganggap acara semacam itu tidak penting",1]], p:"Berpartisipasi aktif dalam kegiatan kebangsaan memperkuat komitmen pada Pancasila. Menolak karena menganggap tidak penting menunjukkan sikap kurang peduli."},
{a:"antiradikal", q:"Teman SMA mengajak Anda bergabung dalam komunitas daring yang menormalkan kekerasan demi mencapai tujuan kelompoknya. Sikap Anda...", o:[["Menolak, menjelaskan bahayanya, lalu melaporkan komunitas itu kepada aparat atau platform agar ditindaklanjuti",5],["Menolak ajakan dengan tegas dan mengingatkan temannya agar tidak terjerumus pada paham yang membenarkan kekerasan terhadap sesama",4],["Menolak secara halus lalu memutus komunikasi",3],["Bergabung hanya untuk melihat isinya",2],["Bergabung karena tertarik pada solidaritas anggotanya",1]], p:"Menolak dan melapor melindungi diri sekaligus masyarakat dari paham kekerasan. Bergabung, walau hanya mengintip, berisiko terpengaruh."},
{a:"antiradikal", q:"Atasan meminta Anda menyusun materi penyuluhan wawasan kebangsaan untuk warga di wilayah kerja Anda. Yang Anda lakukan...", o:[["Menyusun materi dari sumber resmi, memakai contoh sehari-hari, lalu menyajikannya secara interaktif agar mudah dipahami warga",5],["Mengumpulkan bahan dari sumber tepercaya tentang Pancasila dan UUD 1945, lalu menyusunnya menjadi presentasi yang ringkas dan runtut",4],["Menyalin materi lama tanpa memperbaruinya",3],["Meminta rekan membuatkan materi tersebut",2],["Menolak karena tidak sesuai bidang Anda",1]], p:"Materi dari sumber resmi yang disajikan menarik memperkuat pemahaman kebangsaan. Menyalin atau melempar tugas mengurangi kualitas penyuluhan."},
{a:"antiradikal", q:"Seorang kenalan lama sering menyalahkan negara atas semua masalah dan mulai berbicara tentang melawan secara kekerasan. Sikap Anda...", o:[["Mendengarkan keluhannya, mengarahkan pada jalur aspirasi yang sah, dan melapor kepada pihak berwenang jika ia mulai mengancam",5],["Menenangkan dan mengajaknya menyalurkan kekecewaan lewat cara damai, seperti menyampaikan aspirasi kepada pihak yang berwenang atau perwakilan warga",4],["Membiarkannya berbicara tanpa menanggapi",3],["Menghindari kenalan itu mulai sekarang",2],["Menyemangatinya agar berani melawan",1]], p:"Mengarahkan pada jalur aspirasi yang sah dan melapor bila mengancam adalah sikap moderat dan bertanggung jawab. Mendukung kekerasan membahayakan banyak orang."},
{a:"antiradikal", q:"Di media sosial, lambang negara dilecehkan oleh sebuah akun dengan unggahan yang memancing kemarahan banyak orang. Yang Anda lakukan...", o:[["Tidak ikut menyebarkan, melaporkan unggahan lewat fitur resmi, dan mengajak orang lain menanggapi dengan tenang",5],["Melaporkan unggahan itu kepada platform dan menghindari saling serang di kolom komentar yang justru memperkeruh suasana",4],["Mengabaikan karena sudah banyak yang melaporkan",3],["Membalas dengan komentar penuh amarah",2],["Mencari data pribadi pemilik akun lalu menyebarkannya",1]], p:"Melapor lewat jalur resmi dan menjaga ketenangan lebih efektif daripada amarah. Menyebar data pribadi adalah tindakan main hakim sendiri."},
{a:"antiradikal", q:"Seorang rekan menyatakan bahwa aturan negara tidak wajib ditaati karena hanya buatan manusia dan mengajak orang lain tidak membayar kewajiban tertentu. Sikap Anda...", o:[["Meluruskan dengan baik bahwa menaati hukum adalah kewajiban warga negara, lalu melaporkan ajakan itu jika terus disebarkan",5],["Menjelaskan secara santun bahwa aturan dibuat untuk kepentingan bersama dan mengingatkan rekan agar tidak mengajak orang lain melanggar",4],["Tidak menanggapi karena itu pendapat pribadinya",3],["Menjauhi rekan tersebut tanpa penjelasan",2],["Ikut tidak menaati aturan karena merasa ada benarnya",1]], p:"Taat hukum adalah wujud kesetiaan pada UUD 1945 dan NKRI. Mengabaikan ajakan melanggar atau ikut serta melemahkan ketertiban."},
{a:"antiradikal", q:"Anda mendengar rencana unjuk rasa yang disertai ancaman akan merusak fasilitas umum jika tuntutan tidak dipenuhi. Yang Anda lakukan...", o:[["Melapor kepada aparat yang berwenang dengan informasi yang jelas, dan mengajak warga menyampaikan aspirasi secara damai",5],["Mengingatkan orang yang merencanakan bahwa menyampaikan pendapat dilindungi hukum tetapi tidak boleh disertai kekerasan atau perusakan",4],["Menyimpan informasi itu sendiri",3],["Menyebarkan informasi itu tanpa memastikan kebenarannya",2],["Ikut merencanakan agar tuntutan didengar",1]], p:"Menyampaikan pendapat itu hak, tetapi ancaman kekerasan harus dilaporkan agar dicegah. Menyimpan, menyebar tanpa cek, atau ikut terlibat tidak tepat."},
{a:"antiradikal", q:"Grup alumni Anda ramai memuji pelaku aksi kekerasan sebagai pahlawan karena memperjuangkan cita-cita kelompoknya. Sikap Anda...", o:[["Menyampaikan bahwa kekerasan tidak dapat dibenarkan, lalu melaporkan konten pujian itu kepada admin atau pihak berwenang",5],["Menegaskan dengan sopan bahwa kekerasan merugikan banyak orang dan mengajak anggota grup membahas cara damai memperjuangkan cita-cita",4],["Keluar dari grup tanpa memberi alasan",3],["Diam karena tidak ingin berdebat",2],["Ikut memuji agar tidak dikucilkan",1]], p:"Menolak pembenaran kekerasan dan melapor menjaga ruang diskusi tetap sehat. Diam atau ikut memuji membiarkan paham kekerasan tumbuh."},
{a:"antiradikal", q:"Sejumlah warga mulai memboikot tetangga yang berbeda pandangan dan menuduhnya tidak setia pada negara tanpa bukti. Yang Anda lakukan...", o:[["Menghentikan tuduhan itu dengan tenang, mengajak warga berdialog, dan menyerahkan dugaan pelanggaran kepada pihak berwenang",5],["Mengingatkan warga bahwa perbedaan pandangan tidak sama dengan ketidaksetiaan, serta meminta mereka tidak menyebarkan tuduhan tanpa bukti",4],["Tidak ikut memboikot tetapi juga tidak membela",3],["Ikut menjauhi tetangga itu agar tidak dikucilkan",2],["Ikut menuduh dan mengajak warga lain menjauhinya",1]], p:"Persatuan terjaga bila perbedaan pandangan tidak dihukum dengan tuduhan tanpa bukti. Ikut memboikot atau menuduh memecah kerukunan."},
];
